using ModelContextProtocol.Server;
using System.Text.Json;

[McpResource(Uri = "config://app/settings", Name = "App Settings",
    Description = "Returns the current application configuration")]
public class ConfigResource
{
    public static McpResourceContent Read()
    {
        var config = new
        {
            Environment = "production",
            MaxConnections = 100,
            FeatureFlags = new { DarkMode = true, BetaFeatures = false }
        };

        return McpResourceContent.TextContent(
            "config://app/settings",
            JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true }),
            "application/json");
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

