using ModelContextProtocol.Server;
using ModelContextProtocol.Protocol;
using System.Text.Json;

[McpServerResourceType]
public class ConfigResource
{
    [McpServerResource(Uri = "config://app/settings", Name = "App Settings",
        Description = "Returns the current application configuration")]
    public static ReadResourceResult GetSettings()
    {
        var config = new
        {
            Environment = "production",
            MaxConnections = 100,
            FeatureFlags = new { DarkMode = true, BetaFeatures = false }
        };

        return new ReadResourceResult
        {
            Contents = [new TextResourceContents
            {
                Uri = "config://app/settings",
                MimeType = "application/json",
                Text = JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true })
            }]
        };
    }
}

